-- ADMIN-RDS-14: isolated media registry foundation; policy remains DISABLED.
-- Run the ENTIRE file once: HOD Staging / hod_staging / hod_dev_migration.
-- Database-only fixture rows roll back. No S3 bytes, cloud policy or provider change.
BEGIN;
SET LOCAL lock_timeout='3s';SET LOCAL statement_timeout='90s';SET LOCAL search_path=pg_catalog,public,pg_temp;
SET LOCAL ROLE hod_migration;
DO $target$ BEGIN
 IF current_database()<>'hod_staging' OR session_user<>'hod_dev_migration' OR current_user<>'hod_migration'
 THEN RAISE EXCEPTION 'Use HOD Staging / hod_staging / hod_dev_migration'; END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='hod_migration' AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication)
 OR NOT EXISTS(SELECT FROM pg_roles WHERE rolname='hod_admin_app' AND NOT rolcanlogin AND NOT rolinherit AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication)
 OR EXISTS(SELECT FROM pg_roles WHERE rolname<>'hod_admin_app' AND pg_has_role('hod_admin_app',oid,'MEMBER'))
 OR NOT has_database_privilege('hod_migration',current_database(),'CREATE')
 THEN RAISE EXCEPTION 'Media owner/capability isolation differs'; END IF;
 IF EXISTS(SELECT FROM pg_default_acl WHERE defaclrole='hod_migration'::regrole)
 THEN RAISE EXCEPTION 'Owner default ACL changed; review before installation'; END IF;
END $target$;
CREATE TEMP TABLE admin_media14_scope ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"name":"public.admin_identities","fingerprint":"400755f0312e93f7dbd85f8a17b2ca4d"},{"name":"public.profiles","fingerprint":"bfd124193706eeffda3f6a0e0cb04f47"}]'::jsonb) AS s(name text,fingerprint text);
DO $dependencies$ DECLARE r record;BEGIN
 FOR r IN SELECT * FROM admin_media14_scope ORDER BY name LOOP
  EXECUTE format('LOCK TABLE %s IN SHARE UPDATE EXCLUSIVE MODE',r.name);
  IF (SELECT md5((jsonb_build_object(
 'owner',c.relowner::regrole::text,'kind',c.relkind,'rls',c.relrowsecurity,'force',c.relforcerowsecurity,
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
   'identity',a.attidentity,'generated',a.attgenerated,'not_null',a.attnotnull,
   'default_hash',md5(pg_get_expr(d.adbin,d.adrelid)),
   'acl',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.grantor,x.grantee,x.privilege_type),'[]'::jsonb)
     FROM aclexplode(a.attacl) x )) ORDER BY a.attnum)
   FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
   WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'acl',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.grantor,x.grantee,x.privilege_type),'[]'::jsonb)
   FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x ),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,
   'permissive',p.polpermissive,'roles',p.polroles,'using',pg_get_expr(p.polqual,p.polrelid),
   'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname),'[]'::jsonb)
   FROM pg_policy p WHERE p.polrelid=c.oid ),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,
   'definition',md5(pg_get_triggerdef(t.oid)),'function',md5(pg_get_functiondef(t.tgfoid))) ORDER BY t.tgname),'[]'::jsonb)
   FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid)) ORDER BY k.conname),'[]'::jsonb)
   FROM pg_constraint k WHERE k.conrelid=c.oid)))::text) FROM pg_class c WHERE c.oid=to_regclass(r.name)) IS DISTINCT FROM r.fingerprint
  THEN RAISE EXCEPTION 'Media identity dependency differs: %',r.name; END IF;
 END LOOP;
END $dependencies$;
DO $manifest$ BEGIN
 IF (jsonb_build_object(
 'schema',(SELECT jsonb_build_object('owner',n.nspowner::regrole::text,'acl',
  (SELECT jsonb_agg(jsonb_build_object('grantor',a.grantor::regrole::text,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END,
   'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee::regrole::text,a.privilege_type)
   FROM aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a)) FROM pg_namespace n WHERE n.nspname='admin_media'),
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',c.relowner::regrole::text,'kind',c.relkind,'rls',c.relrowsecurity,'force',c.relforcerowsecurity,
  'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,
   'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),
   'acl',(SELECT jsonb_agg(jsonb_build_object('grantor',x.grantor::regrole::text,'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE x.grantee::regrole::text END,
    'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantee::regrole::text,x.privilege_type) FROM aclexplode(a.attacl) x)) ORDER BY a.attnum)
   FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
  'acl',(SELECT jsonb_agg(jsonb_build_object('grantor',a.grantor::regrole::text,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END,
   'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee::regrole::text,a.privilege_type) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a),
  'constraints',(SELECT jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid)) ORDER BY k.conname)
   FROM pg_constraint k WHERE k.conrelid=c.oid AND k.contype<>'n'),
  'indexes',(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY pg_get_indexdef(i.indexrelid)) FROM pg_index i WHERE i.indrelid=c.oid),
  'policies',(SELECT jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,
   'roles',(SELECT jsonb_agg(r::regrole::text ORDER BY r::regrole::text) FROM unnest(p.polroles) r),
   'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname) FROM pg_policy p WHERE p.polrelid=c.oid),
  'triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) ORDER BY t.tgname)
   FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) ORDER BY c.relname)
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='admin_media' AND c.relkind NOT IN('i','I')),
 'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),
  'return',pg_get_function_result(p.oid),'language',l.lanname,'owner',p.proowner::regrole::text,'definer',p.prosecdef,
  'config',p.proconfig,'set',p.proretset,'strict',p.proisstrict,'leakproof',p.proleakproof,'kind',p.prokind,'volatile',p.provolatile,
  'parallel',p.proparallel,'defaults',p.pronargdefaults,'body',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),
  'acl',(SELECT jsonb_agg(jsonb_build_object('grantor',a.grantor::regrole::text,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END,
   'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee::regrole::text,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) ORDER BY p.proname)
  FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='admin_media'))) IS DISTINCT FROM '{"schema":{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"USAGE"},{"grantee":"hod_migration","grantor":"hod_migration","grantable":false,"privilege":"CREATE"},{"grantee":"hod_migration","grantor":"hod_migration","grantable":false,"privilege":"USAGE"}],"owner":"hod_migration"},"tables":[{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"SELECT"},{"grantee":"hod_migration","grantor":"hod_migration","grantable":false,"privilege":"DELETE"},{"grantee":"hod_migration","grantor":"hod_migration","grantable":false,"privilege":"INSERT"},{"grantee":"hod_migration","grantor":"hod_migration","grantable":false,"privilege":"MAINTAIN"},{"grantee":"hod_migration","grantor":"hod_migration","grantable":false,"privilege":"REFERENCES"},{"grantee":"hod_migration","grantor":"hod_migration","grantable":false,"privilege":"SELECT"},{"grantee":"hod_migration","grantor":"hod_migration","grantable":false,"privilege":"TRIGGER"},{"grantee":"hod_migration","grantor":"hod_migration","grantable":false,"privilege":"TRUNCATE"},{"grantee":"hod_migration","grantor":"hod_migration","grantable":false,"privilege":"UPDATE"}],"rls":true,"kind":"r","name":"admissions","force":true,"owner":"hod_migration","columns":[{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"admission_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"operation_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"actor_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"actor_issuer","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"actor_subject","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"bucket","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"object_key","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"canonical_url","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"sha256","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"byte_length","type":"integer","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"mime","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"UPDATE"}],"name":"object_version","type":"text","default":null,"identity":"","not_null":false,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"policy","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"verifier","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"}],"name":"evidence","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"INSERT"},{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"UPDATE"}],"name":"status","type":"text","default":"''pending''::text","identity":"","not_null":true,"generated":""},{"acl":null,"name":"created_at","type":"timestamp with time zone","default":"clock_timestamp()","identity":"","not_null":true,"generated":""},{"acl":[{"grantee":"hod_admin_app","grantor":"hod_migration","grantable":false,"privilege":"UPDATE"}],"name":"verified_at","type":"timestamp with time zone","default":null,"identity":"","not_null":false,"generated":""}],"indexes":["CREATE UNIQUE INDEX admissions_bucket_object_key_key ON admin_media.admissions USING btree (bucket, object_key)","CREATE UNIQUE INDEX admissions_canonical_url_key ON admin_media.admissions USING btree (canonical_url)","CREATE UNIQUE INDEX admissions_operation_id_key ON admin_media.admissions USING btree (operation_id)","CREATE UNIQUE INDEX admissions_pkey ON admin_media.admissions USING btree (admission_id)"],"policies":[{"name":"owner_admissions","check":"true","roles":["hod_migration"],"using":"true","command":"*","permissive":true},{"name":"runtime_admission_insert","check":"((status = ''pending''::text) AND (evidence = ''new-upload-intent''::text))","roles":["hod_admin_app"],"using":null,"command":"a","permissive":true},{"name":"runtime_admission_insert_guard","check":"((status = ''pending''::text) AND (evidence = ''new-upload-intent''::text))","roles":["hod_admin_app"],"using":null,"command":"a","permissive":false},{"name":"runt